      // Convert files to base64 with proper formatting
      for (let i = 0; i < addPhotos.length; i++) {
        const file = addPhotos[i];
        try {
          const base64 = await fileToBase64(file);
          additionalPhotosData.push({
            base64: base64,
            name: file.name,
            type: file.type,
            size: file.size
          });
          console.log(`Photo ${i+1} converted successfully:`, file.name);
        } catch (error) {
          console.error(`Error converting photo ${i+1}:`, error);
        }
      }
    }

    // Construct payload - SIMPLIFIED FOR TESTING
    const payload = {
      name: reviewData.name.trim(),
      email: user?.email || "unknown@example.com",
      rating: reviewData.rating,
      comment: reviewData.comment.trim(),
      photo: user?.picture || "No photo", // Google profile photo URL
      additionalPhotos: additionalPhotosData, // Array of photo objects
      action: "submitReview"
    };

    console.log("Final payload structure:", {
      name: payload.name,
      email: payload.email,
      rating: payload.rating,
      commentLength: payload.comment.length,
      photo: payload.photo ? "Google photo URL present" : "No photo",
      additionalPhotosCount: payload.additionalPhotos.length,
      action: payload.action
    });

    // DEBUG: Test the API connection first
    console.log("Testing API connection...");
    const testResponse = await fetch(`${GOOGLE_SCRIPT_URL}?action=test`);
    const testData = await testResponse.json();
    console.log("API test result:", testData);

    if (!testData.success) {
      throw new Error("API is not responding properly");
    }

    // METHOD 1: Try POST request first (preferred for large data)
    console.log("Attempting POST request...");
    
    // Create a simpler payload for POST to avoid CORS issues
    const postPayload = {
      name: payload.name,
      email: payload.email,
      rating: payload.rating,
      comment: payload.comment,
      photo: payload.photo,
      action: "submitReview"
    };

    // Only include additionalPhotos if they exist and are small enough
    if (additionalPhotosData.length > 0) {
      // For POST, we can include the photos
      postPayload.additionalPhotos = additionalPhotosData;
    }

    try {
      const response = await fetch(GOOGLE_SCRIPT_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(postPayload),
      });

      console.log("POST response status:", response.status);

      if (response.ok) {
        const data = await response.json();
        console.log("POST success response:", data);

        if (data.success) {
          showFeedbackDialog("Thank you! Your review was submitted successfully.", "success");
          handleReviewDialogClose();
          setHasReviewed(true);
          return;
        } else {
          throw new Error(data.message || "Submission failed");
        }
      } else {
        throw new Error(`HTTP error: ${response.status}`);
      }
    } catch (postError) {
      console.log("POST method failed, trying GET fallback:", postError);

      // METHOD 2: Fallback to GET request (for CORS issues)
      // For GET requests, we need to be careful with URL length limits
      const params = new URLSearchParams({
        action: "submit",
        name: payload.name,
        email: payload.email,
        rating: payload.rating,
        comment: payload.comment,
        photo: payload.photo,
        timestamp: new Date().toISOString()
      });

      // For GET requests, we CANNOT include large base64 data due to URL length limits
      // So we'll submit without additional photos in GET mode
      if (additionalPhotosData.length > 0) {
        console.warn("GET method: Skipping additional photos due to URL length limits");
        params.append('hasAdditionalPhotos', 'true');
        params.append('additionalPhotosCount', additionalPhotosData.length.toString());
      }

      const getUrl = `${GOOGLE_SCRIPT_URL}?${params.toString()}`;
      console.log("GET URL length:", getUrl.length);
      
      // Check if URL is too long (URLs should generally be under 2000 characters)
      if (getUrl.length > 2000) {
        console.warn("URL too long, truncating comment");
        params.set('comment', payload.comment.substring(0, 100) + "...[truncated]");
      }

      const getResponse = await fetch(getUrl);
      const getData = await getResponse.json();
      
      console.log("GET response:", getData);

      if (getData.success) {
        if (additionalPhotosData.length > 0) {
          showFeedbackDialog("Review submitted! Note: Additional photos were not included due to technical limitations.", "info");
        } else {
          showFeedbackDialog("Thank you! Your review was submitted.", "success");
        }
        handleReviewDialogClose();
        setHasReviewed(true);
      } else {
        throw new Error(getData.message || "GET submission failed");
      }
    }

  } catch (error) {
    console.error("Final submission error:", error);
    
    // More user-friendly error messages
    if (error.message.includes("Failed to fetch")) {
      showFeedbackDialog("Network error. Please check your internet connection and try again.", "error");
    } else if (error.message.includes("API is not responding")) {
      showFeedbackDialog("Service temporarily unavailable. Please try again in a few minutes.", "error");
    } else if (error.message.includes("CORS")) {
      showFeedbackDialog("Browser security restriction. Please try using a different browser or contact support.", "error");
    } else {
      showFeedbackDialog(`Submission failed: ${error.message}`, "error");
    }
  } finally {
    setLoading(false);
  }
};


